// The map page's Content-Security-Policy travels as a <meta http-equiv> in the BUILT page,
// generated by gen-headers.mjs from the same cspValue() the _headers line used to carry.
// Why (spec U7, decision D3): Cloudflare caps a _headers LINE at 2,000 characters and the
// map policy had 164 left, so no new picture host could be added. A <meta> has no line cap.
//
// What a meta CANNOT do, and the policy must therefore not rely on: frame-ancestors,
// report-uri, report-to and sandbox are ignored in a meta. The policy uses none of them.
// And a meta only governs what the parser sees AFTER it, so it must be the first thing in
// <head> (a leading <meta charset> may precede it, to stay inside the 1024-byte pre-scan). The _headers block keeps "! Content-Security-Policy" so the sitewide same-origin
// header does not intersect-narrow the meta policy.
//
// Needs the build: `bash scripts/build-site.sh --configDir site-config --minify`.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { existsSync, readFileSync } from 'node:fs';
import { cspValue } from './gen-headers.mjs';
import { stateOrigins, DASHBOARD_PATH } from '../../themes/headlessmode/static/js/quiet-corners-maps/state-pages.js';

const PAGE = new URL('../../public/quiet-corners/index.html', import.meta.url);
const skip = existsSync(PAGE) ? false : 'no built public/quiet-corners/index.html (run scripts/build-site.sh)';
const html = skip ? '' : readFileSync(PAGE, 'utf8');
const head = skip ? '' : html.slice(html.search(/<head[\s>]/i), html.search(/<\/head>|<body[\s>]/i));
const metas = [...head.matchAll(/<meta\b[^>]*http-equiv=["']?Content-Security-Policy["']?[^>]*>/gi)].map((m) => m[0]);
const contentOf = (tag) => (tag.match(/\bcontent="([^"]*)"/) || [])[1];

test('the built map page carries exactly one CSP meta', { skip }, () => {
  assert.equal(metas.length, 1, `expected exactly 1 CSP <meta> in <head> of ${DASHBOARD_PATH}, found ${metas.length}`);
});

test('the meta policy equals cspValue() exactly: same origins, same directives', { skip }, () => {
  assert.equal(contentOf(metas[0]), cspValue(stateOrigins()));
});

test('the charset declaration sits in the first 1024 bytes and the CSP meta precedes every resource-loading element', { skip }, () => {
  const cs = /<meta\b[^>]*\bcharset=/i.exec(html);
  assert.ok(cs, 'no <meta charset> in the built page');
  const at = Buffer.byteLength(html.slice(0, cs.index), 'utf8');
  assert.ok(at < 1024, `<meta charset> starts at byte ${at}; browsers only pre-scan the first 1024 bytes`);
  const cspAt = html.indexOf(metas[0]);
  const loader = /<(?:link|script|img|style)\b/gi;
  loader.lastIndex = html.search(/<head[\s>]/i);
  const first = loader.exec(html);
  assert.ok(!first || cspAt < first.index, `a <${first && first[0].slice(1)}> at ${first && first.index} precedes the CSP meta at ${cspAt}`);
});

test('the meta is the first child of <head> (apart from a leading <meta charset>), so it governs everything the parser sees after it', { skip }, () => {
  const afterOpen = head.replace(/^<head[^>]*>\s*/i, '').replace(/^<meta\b[^>]*\bcharset=[^>]*>\s*/i, '');
  assert.ok(afterOpen.startsWith(metas[0]), `first child of <head> is: ${afterOpen.slice(0, 80)}`);
});

test('the policy uses no directive a <meta> cannot carry', { skip }, () => {
  const names = contentOf(metas[0]).split(';').map((d) => d.trim().split(/\s+/)[0]);
  for (const bad of ['frame-ancestors', 'report-uri', 'report-to', 'sandbox']) {
    assert.ok(!names.includes(bad), `${bad} is ignored in a <meta>; it cannot live in this policy`);
  }
});

test('the map path still detaches the sitewide CSP header and sets none of its own', { skip }, () => {
  const headers = readFileSync(new URL('../../public/_headers', import.meta.url), 'utf8');
  const block = headers.slice(headers.indexOf(`\n${DASHBOARD_PATH}\n`) + 1).split(/\n(?=\S)/)[0];
  assert.match(block, /^\s+! Content-Security-Policy$/m, 'the sitewide header is no longer detached on the map path');
  assert.ok(!/^\s+Content-Security-Policy:/m.test(block), 'a header CSP on the map path would intersect the meta policy');
});

test('the policy text is unchanged by the move: origins and directives are the pre-U7 set', { skip }, () => {
  const p = contentOf(metas[0]);
  for (const d of ["default-src 'self'", "script-src 'self'", "worker-src 'self' blob:", "frame-src 'none'",
    "object-src 'none'", "base-uri 'self'", "form-action 'self'"]) assert.ok(p.split('; ').includes(d), `${d} missing`);
  assert.equal(p.split('; ').length, 11, 'the directive count changed');
});

// Unit level, no build needed: the injector the build runs.
import { injectCspMeta, headCspMetas } from './helpers/headers.mjs';

test('injectCspMeta opens <head>, replaces rather than stacks, and round-trips the policy', () => {
  const src = '<!doctype html><html><head><meta charset=UTF-8><title>t</title></head><body></body></html>';
  const policy = cspValue(stateOrigins());
  const once = injectCspMeta(src, policy);
  assert.equal(injectCspMeta(once, policy), once, 'running twice must not stack a second policy');
  const seen = headCspMetas(once);
  assert.deepEqual(seen.policies, [policy]);
  assert.ok(seen.first);
  assert.throws(() => injectCspMeta('<p>no head</p>', policy), /no <head>/);
});
